/**
 * \file profiler_host_helper.h
 * \brief Host-side profiler helpers — alloc, warmup loop, dump.
 *
 * Only include from host C++ (NOT device/kernel code).
 * Requires: profiler_config.h in include path (generated by CMake configure_file).
 * Requires: acl/acl.h for ACL API types.
 *
 * Usage:
 *   // 1. Allocate
 *   ProfilerBuffer profBuf;
 *   ProfilerAlloc(profBuf);
 *
 *   // 2. Embed device address into tiling data (operator-specific, manual)
 *   hostTilingData.xxx.profBufGm = (uint64_t)profBuf.devicePtr;
 *
 *   // 3. Warmup + launch loop
 *   ProfilerWarmup(profBuf, loopCount, [&]() {
 *       my_kernel_demo(blockDim, stream, ..., tilingAddr);
 *       aclrtSynchronizeStreamWithTimeout(stream, 30000);
 *   });
 *
 *   // 4. Dump
 *   ProfilerDump(profBuf, rankId);
 *
 *   // 5. Free
 *   ProfilerFree(profBuf);
 */

#pragma once

#include "profiler_config.h"
#include "acl/acl.h"
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>
#include <fstream>
#include <functional>

// Buffer size in bytes — derived from config constants.
static constexpr uint32_t PROF_HOST_BUF_TOTAL =
    PROF_N_CORES * PROF_RINGIDX_ALIGN +
    PROF_N_CORES * 4096 * 16;

// Warmup protocol: 20 iterations, drop first 5.
// P2P cold-start ~1.8ms; without warmup, early iterations skew 10-100x.
// profBuf MUST be cleared during dropped iterations (ring buffer overlay).
static constexpr int PROF_WARMUP_TOTAL = 20;
static constexpr int PROF_WARMUP_DROP  = 5;

struct ProfilerBuffer {
    void*    devicePtr = nullptr;
    uint32_t size      = PROF_HOST_BUF_TOTAL;
};

/**
 * Allocate and zero-initialize the profiler buffer on device.
 * Returns ACL_SUCCESS on success.
 */
inline aclError ProfilerAlloc(ProfilerBuffer& buf) {
    aclError ret = aclrtMalloc(&buf.devicePtr, buf.size, ACL_MEM_MALLOC_HUGE_FIRST);
    if (ret != ACL_ERROR_NONE) {
        std::fprintf(stderr, "[PROFILER] aclrtMalloc failed: %d\n", ret);
        return ret;
    }
    ret = aclrtMemset(buf.devicePtr, buf.size, 0, buf.size);
    if (ret != ACL_ERROR_NONE) {
        std::fprintf(stderr, "[PROFILER] aclrtMemset failed: %d\n", ret);
        return ret;
    }
    std::printf("[PROFILER] buffer allocated: %u bytes, %u cores\n",
                buf.size, (uint32_t)PROF_N_CORES);
    return ACL_ERROR_NONE;
}

/**
 * Run warmup + profiling loop.
 *
 * \param buf       Profiler buffer (must be pre-allocated via ProfilerAlloc)
 * \param loopCount Number of measurement iterations AFTER warmup
 * \param launch    Callable that launches the kernel AND synchronizes the stream
 *
 * Total iterations = PROF_WARMUP_TOTAL + loopCount.
 * Buffer is cleared after each of the first PROF_WARMUP_DROP iterations
 * to discard cold-start data.
 */
inline void ProfilerWarmup(ProfilerBuffer& buf, int loopCount,
                           const std::function<void()>& launch) {
    int total = PROF_WARMUP_TOTAL + loopCount;
    for (int i = 0; i < total; i++) {
        launch();
        if (i < PROF_WARMUP_DROP) {
            aclrtMemset(buf.devicePtr, buf.size, 0, buf.size);
        }
    }
}

/**
 * Dump profiler buffer to a binary file: prof_rank{rankId}.bin
 * Returns ACL_SUCCESS on success.
 */
inline aclError ProfilerDump(ProfilerBuffer& buf, uint32_t rankId) {
    std::vector<uint8_t> hostBuf(buf.size);
    aclError ret = aclrtMemcpy(hostBuf.data(), buf.size, buf.devicePtr,
                               buf.size, ACL_MEMCPY_DEVICE_TO_HOST);
    if (ret != ACL_ERROR_NONE) {
        std::fprintf(stderr, "[PROFILER] rank=%u D2H failed: %d\n", rankId, ret);
        return ret;
    }
    char fname[256];
    std::snprintf(fname, sizeof(fname), "prof_rank%u.bin", rankId);
    std::ofstream ofs(fname, std::ios::binary);
    ofs.write(reinterpret_cast<const char*>(hostBuf.data()), buf.size);
    std::printf("[PROFILER] rank=%u dumped to %s (%u bytes)\n",
                rankId, fname, buf.size);
    return ACL_ERROR_NONE;
}

/**
 * Free the profiler buffer.
 */
inline void ProfilerFree(ProfilerBuffer& buf) {
    if (buf.devicePtr) {
        aclrtFree(buf.devicePtr);
        buf.devicePtr = nullptr;
    }
}
